// StringToStringWithFormat creates a new String binding that formats another String binding value
// using the provided format string. The format string should contain exactly one %s placeholder.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//   // greeting.Get() returns "Hello, Alice!"
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	b := &stringToStringWithFormat{
		format: format,
		source: str,
	}

	// Listen to source changes
	str.AddListener(b)

	return b
}

// DataChanged is called when the source string changes.
func (b *stringToStringWithFormat) DataChanged() {
	b.trigger()
}

// Get returns the formatted string value.
func (b *stringToStringWithFormat) Get() (string, error) {
	b.lock.RLock()
	defer b.lock.RUnlock()

	val, err := b.source.Get()
	if err != nil {
		return "", err
	}

	return fmt.Sprintf(b.format, val), nil
}

// Set parses the formatted string back to extract the original value and sets it on the source.
func (b *stringToStringWithFormat) Set(str string) error {
	b.lock.Lock()
	defer b.lock.Unlock()

	var val string
	n, err := fmt.Sscanf(str, b.format, &val)
	if err != nil {
		return fmt.Errorf("failed to parse formatted string: %w", err)

func parseHexByte(hex string, out *uint8) error {
	var val uint8
	for i := 0; i < len(hex); i++ {
		c := hex[i]
		var digit uint8
		switch {
		case '0' <= c && c <= '9':
			digit = c - '0'
		case 'a' <= c && c <= 'f':
			digit = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			digit = c - 'A' + 10
		default:
			return fmt.Errorf("invalid hex character: %c", c)
		}
		val = val*16 + digit
	}
	*out = val
	return nil
}

// Color returns the color for the given name and variant from the JSON theme.
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	var colorMap map[fyne.ThemeColorName]color.Color
	if variant == VariantLight {
		colorMap = t.colorsLight
	} else {
		colorMap = t.colorsDark
	}

	if c, ok := colorMap[name]; ok {
		return c
	}
	// Fallback to default theme
	return DefaultTheme().Color(name, variant)
}

// Font returns the font resource for the given style from the JSON theme.
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Font loading would require additional implementation
	// Fallback to default theme
	return DefaultTheme().Font(style)
}

// Icon returns the icon resource for the given name from the JSON theme.
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icon, ok := t.icons[name]; ok {
		return icon
	}
	// Fallback to default theme
	return DefaultTheme().Icon(name)
}

// Size returns the size for the given name from the JSON theme.
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	// Fallback to default theme
	return DefaultTheme().Size(name)
}

